window.__PAGE_RUNTIME_PARTIALS__["partials/sb10-guia-06-mantenimiento-integral-content.html"] = "\u003cbutton class=\"hamburger\" onclick=\"toggleSidebar()\" aria-label=\"Menú\"\u003e\u0026#9776;\u003c/button\u003e\n\u003cbutton class=\"btn-sb-expand\" onclick=\"showSidebar()\" title=\"Mostrar barra lateral\"\u003e\u0026#9776;\u003c/button\u003e\n\u003c!-- Generado por herramientas/generar_guias_mantenimiento.py (2026-10-22) desde el PDF original del\n     instructor (competencia 220501001, RAP 02). No editar a mano: editar mant_specs.py y regenerar. --\u003e\n\n\u003cdiv class=\"layout app-layout\"\u003e\n  \u003cnav class=\"sidebar\" id=\"sidebar\"\u003e\n    \u003cdiv class=\"sidebar-logo\"\u003e\n      \u003cdiv class=\"badge\"\u003eSENA \u0026middot; FPI\u003c/div\u003e\n      \u003ch2\u003eGu\u0026iacute;a 6 - Realizar mantenimiento integral de los sistemas de cómputo\u003c/h2\u003e\n      \u003cp\u003eSistemas Teleinform\u0026aacute;ticos\u003c/p\u003e\n      \u003cbutton class=\"btn-sb-collapse\" onclick=\"hideSidebar()\" title=\"Ocultar barra lateral\"\u003e\u0026#9664;\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"sidebar-ficha u-hidden\" id=\"sb-ficha-ok\"\u003e\n      \u003cdiv class=\"sf-label\"\u003eTu grupo\u003c/div\u003e\n      \u003cdiv class=\"sf-inst\" id=\"sb-inst\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-meta\" id=\"sb-grupo-meta\"\u003e\u003c/div\u003e\n      \u003cdiv class=\"sf-badge\" id=\"sb-badge\"\u003e\u003c/div\u003e\n    \u003c/div\u003e\n    \u003cdiv class=\"sidebar-noficha\" id=\"sb-ficha-warn\"\u003e\n      \u003ca href=\"index.html\"\u003eInicio | Seleccionar grupo / ficha\u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"progress-wrap\"\u003e\n      \u003cdiv class=\"progress-label\"\u003e\n        \u003cspan\u003eProgreso\u003c/span\u003e\n        \u003cspan id=\"progressValue\"\u003e0%\u003c/span\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"progress-bar-bg\"\u003e\n        \u003cdiv class=\"progress-bar\" id=\"progressBar\"\u003e\u003c/div\u003e\n      \u003c/div\u003e\n      \u003cp class=\"progress-note\"\u003eEl avance se guarda localmente en este navegador.\u003c/p\u003e\n      \u003cbutton type=\"button\" class=\"reset-button\" id=\"resetProgress\"\u003eReiniciar respuestas\u003c/button\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eInformaci\u0026oacute;n\u003c/div\u003e\n      \u003ca class=\"nav-link active\" href=\"#identificacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128203;\u003c/span\u003e Identificaci\u0026oacute;n\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#presentacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128075;\u003c/span\u003e Presentaci\u0026oacute;n\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eActividades\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#reflexion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128172;\u003c/span\u003e 3.1 Reflexi\u0026oacute;n Inicial\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#contexto\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128269;\u003c/span\u003e 3.2 Contextualizaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#apropiacion\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128218;\u003c/span\u003e 3.3 Apropiaci\u0026oacute;n\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#transferencia\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128640;\u003c/span\u003e 3.4 Transferencia\n        \u003cspan class=\"check\"\u003e\u0026#10003;\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eRecursos\u003c/div\u003e\n      \u003ca class=\"nav-link\" href=\"#control-avance\" onclick=\"setActive(this)\"\u003e\u003cspan class=\"icon\"\u003e\u0026#9989;\u003c/span\u003e Control de avance\u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#materiales\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128193;\u003c/span\u003e Materiales de apoyo\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#evidencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128202;\u003c/span\u003e Evidencias\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#glosario\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128214;\u003c/span\u003e Glosario\n      \u003c/a\u003e\n      \u003ca class=\"nav-link\" href=\"#referencias\" onclick=\"setActive(this)\"\u003e\n        \u003cspan class=\"icon\"\u003e\u0026#128279;\u003c/span\u003e Referencias\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"nav-section\"\u003e\n      \u003cdiv class=\"nav-label\"\u003eGu\u0026iacute;a asignada\u003c/div\u003e\n      \u003ca class=\"nav-guide current\" id=\"currentGuideNavLink\" href=\"santa-barbara-10a-guia-06-mantenimiento-integral.html\" data-current-file=\"santa-barbara-10a-guia-06-mantenimiento-integral.html\"\u003e\n        \u003cspan class=\"g-icon\"\u003e\u0026#128736;\u003c/span\u003e\n        \u003cspan class=\"g-info\"\u003e\n          \u003cspan class=\"g-num\"\u003eGu\u0026iacute;a 6\u003c/span\u003e\n          \u003cspan class=\"g-name\" id=\"currentGuideNavLabel\"\u003eRealizar mantenimiento integral | 10A\u003c/span\u003e\n        \u003c/span\u003e\n        \u003cspan class=\"g-tag actual\"\u003eActual\u003c/span\u003e\n      \u003c/a\u003e\n    \u003c/div\u003e\n\n    \u003ca class=\"nav-home-link\" href=\"calendario-academico-2026.html\"\u003e\u0026#128197; \u003cspan\u003eCalendario 2026\u003c/span\u003e\u003c/a\u003e\n    \u003ca class=\"nav-home-link\" href=\"index.html\"\u003e\u0026#127968; \u003cspan\u003eVolver al Inicio\u003c/span\u003e\u003c/a\u003e\n  \u003c/nav\u003e\n\n  \u003cdiv class=\"main app-main\"\u003e\n    \u003cdiv class=\"topbar\"\u003e\n      \u003cdiv class=\"topbar-title\"\u003e\n        \u003cstrong\u003eGu\u0026iacute;a 6 - Realizar mantenimiento integral de los sistemas de cómputo\u003c/strong\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"topbar-meta\"\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#9201;\u003c/span\u003e\u003cspan\u003e88 horas\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#128197;\u003c/span\u003e\u003cspan\u003e2026\u003c/span\u003e\u003c/span\u003e\n        \u003cspan class=\"meta-item\"\u003e\u003cspan\u003e\u0026#127979;\u003c/span\u003e\u003cspan id=\"topbarCampus\"\u003eSanta Bárbara | Grado 10\u003c/span\u003e\u003c/span\u003e\n      \u003c/div\u003e\n    \u003c/div\u003e\n\n    \u003cdiv class=\"content\"\u003e\n      \u003cdiv class=\"hero\" id=\"inicio\"\u003e\n        \u003cdiv class=\"tag\"\u003eGu\u0026iacute;a 6 | Fase: Ejecución\u003c/div\u003e\n        \u003ch1\u003eRealizar mantenimiento integral de los sistemas de cómputo según procedimiento y manuales técnicos.\u003c/h1\u003e\n        \u003cp\u003eEn esta guía ejecutarás el mantenimiento preventivo físico CRU, incluida la aplicación correcta de pasta térmica, actualizarás e instalarás sistemas operativos, verificarás su licenciamiento, usarás software utilitario de diagnóstico y antivirus, y dispondrás adecuadamente los RAEE generados.\u003c/p\u003e\n        \u003cdiv class=\"hero-meta\"\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127963; SENA \u0026mdash; Servicio Nacional de Aprendizaje\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#128205; Competencia: Mantener equipos de c\u0026oacute;mputo\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#9201; 88 horas\u003c/div\u003e\n          \u003cdiv class=\"hero-meta-item\"\u003e\u0026#127891; C\u0026oacute;digo: 233108 \u0026middot; V1\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"control-avance\" class=\"section-title\"\u003eTu control de avance\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-green\"\u003e\u0026#9989;\u003c/div\u003e\n            \u003cdiv\u003e\u003ch3\u003e\u0026iquest;Qu\u0026eacute; llevas y qu\u0026eacute; te falta?\u003c/h3\u003e\u003cp\u003eSe actualiza solo con tus entregas y respuestas guardadas\u003c/p\u003e\u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv data-act-std-avance\u003e\u003cp class=\"intro-text\"\u003eCargando tu avance...\u003c/p\u003e\u003c/div\u003e\n          \u003cdiv class=\"gnote gnote--recuerda\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128161; Recuerda\u003c/div\u003e\n            \u003cp\u003eEsta tabla se marca sola: \u003cstrong\u003eEntregada\u003c/strong\u003e cuando subes la evidencia a Drive y\n            \u003cstrong\u003eGuardada\u003c/strong\u003e cuando guardas tus respuestas. Lo que siga en Pendiente es lo que te falta.\u003c/p\u003e\u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"identificacion\" class=\"section-title\"\u003eIdentificaci\u0026oacute;n de la Gu\u0026iacute;a\u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-green\"\u003e\u0026#128203;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eDatos del Programa de Formaci\u0026oacute;n\u003c/h3\u003e\n              \u003cp\u003eInformaci\u0026oacute;n oficial del programa y la competencia\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table ident-table\"\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eDenominaci\u0026oacute;n del Programa\u003c/td\u003e\u003ctd\u003eT\u0026eacute;cnico en Sistemas Teleinform\u0026aacute;ticos\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eC\u0026oacute;digo del Programa\u003c/td\u003e\u003ctd\u003e233108 \u0026middot; V1\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eNombre del Proyecto Formativo\u003c/td\u003e\u003ctd\u003eAlfabetización Digital, Asesoría Técnica y Ciberseguridad para la Mejora de Actividades Productivas Locales en la Zona de Influencia del CIAS.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eFase del Proyecto\u003c/td\u003e\u003ctd\u003eEjecución\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eActividad del Proyecto\u003c/td\u003e\u003ctd\u003eImplementar procesos de soporte técnico básico, personalización de herramientas digitales y orientación en ciberseguridad.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eCompetencia\u003c/td\u003e\u003ctd\u003e220501001 — Mantener equipos de cómputo según procedimiento técnico.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eResultado de Aprendizaje\u003c/td\u003e\u003ctd\u003eRAP 02 \u0026mdash; Realizar mantenimiento integral de los sistemas de cómputo según procedimiento y manuales técnicos.\u003c/td\u003e\u003c/tr\u003e\n                \u003ctr\u003e\u003ctd\u003eDuraci\u0026oacute;n\u003c/td\u003e\u003ctd\u003e88 horas\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003cdiv id=\"presentacion\" class=\"section-title\"\u003ePresentaci\u0026oacute;n\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eEmpieza por aquí:\u003c/strong\u003e conoce de qué trata la guía y qué vas a lograr. Léela completa antes de comenzar las actividades.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--ruta\"\u003e\n        \u003cdiv class=\"gnote__label\"\u003e🧭 ¿Cómo trabajar esta guía? Paso a paso\u003c/div\u003e\n        \u003col\u003e\n          \u003cli\u003e\u003cstrong\u003eLee la teoría\u003c/strong\u003e de las secciones de contextualización antes de resolver las actividades.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eResuelve cada actividad\u003c/strong\u003e en orden. Escribe tus respuestas en los campos de la guía.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eGuarda tus respuestas\u003c/strong\u003e con el botón de cada actividad. Tu avance queda guardado en este navegador.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eEntrega las evidencias\u003c/strong\u003e que lo pidan con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e. Quedan en la carpeta de tu ficha.\u003c/li\u003e\n          \u003cli\u003e\u003cstrong\u003eRevisa \"Tu control de avance\"\u003c/strong\u003e (arriba): te muestra qué llevas Entregado, Guardado y Pendiente.\u003c/li\u003e\n        \u003c/ol\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-blue\"\u003e\u0026#128075;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eBienvenida a la Gu\u0026iacute;a\u003c/h3\u003e\n              \u003cp\u003eConoce el contexto, el alcance y las metas de este recorrido formativo\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cp class=\"intro-text\"\u003e¡Bienvenido, aprendiz! En San Pablo de Borbur y la región de Boyacá, papelerías, misceláneas, droguerías y pequeños negocios familiares dependen cada vez más de sus computadores para facturar, llevar inventarios y comunicarse con proveedores. Sin embargo, muy pocos cuentan con un plan de mantenimiento: los equipos se intervienen solo cuando ya fallaron, casi siempre en el peor momento, y nadie sabe qué hacer con las baterías y piezas dañadas que se van acumulando. Un técnico que sabe ejecutar un mantenimiento integral — físico y lógico — y disponer correctamente los residuos electrónicos, evita paradas de operación, alarga la vida útil de los equipos y protege la información del negocio.\u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003eEn esta guía usted desarrollará el RAP 02 de la competencia «Mantener equipos de cómputo según procedimiento técnico»: ejecutará el mantenimiento preventivo físico CRU (Customer Replaceable Unit), incluida la aplicación correcta de pasta térmica, actualizará e instalará sistemas operativos, verificará su licenciamiento y usará software utilitario de diagnóstico y antivirus, y dispondrá adecuadamente los RAEE (Residuos de Aparatos Eléctricos y Electrónicos) generados. El caso guía de esta guía es la \u003cstrong\u003ePapelería y Miscelánea El Nogal\u003c/strong\u003e, San Pablo de Borbur (Boyacá), un negocio familiar que nunca ha recibido mantenimiento programado en sus computadores y que además tiene una batería de portátil dañada sin saber cómo desecharla. Usted será el técnico que la ayude a resolver ambas situaciones.\u003c/p\u003e\n          \u003cp class=\"intro-text\"\u003eTrabajará en cuatro momentos: primero reflexionará sobre el caso de El Nogal; luego estudiará los conceptos clave de mantenimiento integral (hardware, pasta térmica, sistemas operativos, software utilitario y RAEE) y practicará una inspección externa; después aplicará ese conocimiento ejecutando el mantenimiento físico y lógico sobre equipos reales; y finalmente realizará un laboratorio integrador sobre el equipo del caso, con disposición de RAEE y un informe técnico final que sustentará ante el instructor.\u003c/p\u003e\n          \u003cdiv class=\"info-box u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128737; Seguridad durante las prácticas, para cuidar a las personas, los equipos y el ambiente\u003c/div\u003e\n            \u003col class=\"u-steps-top\"\u003e\n          \u003cli\u003eTrabaje solo en los equipos que el instructor le asigne y con su permiso; no abra un equipo sin la supervisión del instructor.\u003c/li\u003e\n          \u003cli\u003eAntes de abrir un equipo, apáguelo y desconéctelo de la corriente; en portátiles, retire la batería solo si el manual del fabricante lo indica.\u003c/li\u003e\n          \u003cli\u003eColóquese la pulsera antiestática antes de tocar los componentes y no use joyas metálicas ni tenga las manos húmedas.\u003c/li\u003e\n          \u003cli\u003eUse el aire comprimido y el alcohol isopropílico en un lugar ventilado y lejos del fuego. No deje caer ni apriete un componente.\u003c/li\u003e\n          \u003cli\u003eUna batería hinchada, golpeada o con olor extraño no se manipula, no se perfora ni se tira a la basura: apártela y avise de inmediato al instructor.\u003c/li\u003e\n          \u003cli\u003eProteja los datos personales: no los muestre en fotos ni capturas de pantalla.\u003c/li\u003e\n            \u003c/ol\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box green u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128204; Lo que necesitas para esta gu\u0026iacute;a\u003c/div\u003e\n            \u003cp\u003eComputador con suite ofimática (LibreOffice o Microsoft Office), acceso a internet, destornilladores de precisión, pulsera antiestática, soplador de aire comprimido, pasta térmica de repuesto y el material de apoyo suministrado por el instructor. Algunas actividades son de trabajo directo con el instructor y otras de trabajo independiente. Lea siempre las instrucciones completas antes de empezar y guarde cada evidencia con un nombre descriptivo (por ejemplo, FichaTecnica_[TuNombre]_v1.0.pdf). \u003cstrong\u003eSin evidencia, no hay evaluaci\u0026oacute;n.\u003c/strong\u003e\u003c/p\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.1 · ACTIVIDADES DE REFLEXIÓN INICIAL ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"reflexion\" class=\"section-title\"\u003e3.1 · Actividades de Reflexión Inicial\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de reflexión inicial:\u003c/strong\u003e activa lo que ya sabes sobre el tema. Aquí no se evalúa el acierto, sino tu participación.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003eActivar lo que usted ya sabe sobre mantenimiento de equipos y reconocer que el mantenimiento integral no es solo hardware, antes de entrar a los conceptos técnicos. Metodología pedagógica: aprendizaje basado en problemas (ABP), con la técnica activa de lluvia de ideas en equipo. Todo el tiempo de reflexión es trabajo directo con el instructor.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-reflexion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128172;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Reflexión Inicial\u003c/h3\u003e\n              \u003cp\u003e2 actividades · Duración: 2 horas directas\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003c!-- ───────── Actividad 3.1.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003e«Detectives del mantenimiento»: el caso de El Nogal\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e En grupos de 3 o 4 personas, respondan mediante lluvia de ideas (no es necesario entregar producto escrito). Duración: 1 hora directa.\u003c/p\u003e\n              \u003carticle class=\"story-card u-mt-16\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso — Papelería y Miscelánea El Nogal, San Pablo de Borbur (Boyacá)\u003c/h3\u003e\n                \u003cp\u003eEste negocio familiar tiene 3 computadores: facturación, inventario y contabilidad. Nunca han recibido mantenimiento programado. Esta semana, el equipo de facturación va muy lento, tarda varios minutos en abrir el programa contable, y su disco está casi lleno; además, el propietario guarda en un cajón una batería de portátil hinchada y ya no sabe qué hacer con ella.\u003c/p\u003e\n              \u003c/article\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eLluvia de ideas en grupo (3 o 4 personas)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003cp class=\"intro-text u-note-0\"\u003eNo es necesario entregar un producto escrito por el grupo: registra aquí tus propias respuestas como participante de la discusión.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. ¿Qué síntomas del computador de facturación llaman su atención? Enumere al menos 3.\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_311_sintomas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. ¿Qué posibles causas técnicas (físicas o lógicas) podrían explicar cada síntoma?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_311_causas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. ¿Qué relación puede haber entre «disco casi lleno» y «el programa tarda en abrir»?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_311_disco\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. ¿Por qué la batería hinchada del cajón NO debe desecharse en la basura común? ¿Qué harían con ella? (Pista: piensen en el riesgo para las personas y para el ambiente.)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_311_bateria\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. ¿Alguna vez han visto un computador con síntomas parecidos en su casa, colegio o negocio familiar? ¿Qué pasó?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_311_experiencia\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"nogal311DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarNogal311\" class=\"btn-save-response\" onclick=\"actStd_save_nogal311()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_nogal311()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusNogal311\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.1.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.1.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eSocialización en plenaria\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión de arranque\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Compartir el hallazgo más preocupante de cada grupo y cerrar con una idea final en la bitácora. Duración: 1 hora directa.\u003c/p\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eCada grupo comparte en máximo 2 minutos su síntoma más preocupante y la causa que consideran más probable.\u003c/li\u003e\n                  \u003cli\u003eEl instructor registra en el tablero los síntomas y agrupa las causas por tipo: físicas, lógicas o de disposición de residuos (RAEE).\u003c/li\u003e\n                  \u003cli\u003eEscriba en su bitácora una idea final: ¿qué relación encuentra entre «no hacer mantenimiento integral» y «terminar con equipos lentos y residuos sin disponer»?\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eBitácora de cierre\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Síntoma más preocupante que compartió tu grupo y la causa más probable\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_312_sintoma_grupo\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Idea final: ¿qué relación encuentra entre «no hacer mantenimiento integral» y «terminar con equipos lentos y residuos sin disponer»?\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_312_reflexion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"plenaria312DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarPlenaria312\" class=\"btn-save-response\" onclick=\"actStd_save_plenaria312()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_plenaria312()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusPlenaria312\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.2 · CONTEXTUALIZACIÓN E IDENTIFICACIÓN DE CONOCIMIENTOS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"contexto\" class=\"section-title\"\u003e3.2 · Contextualización e Identificación de Conocimientos\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de contextualización:\u003c/strong\u003e aquí están los conceptos y la teoría que necesitas. Estúdialos con calma.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003eConstruir la base conceptual sobre arquitectura de hardware, tipos de mantenimiento, pasta térmica, sistemas operativos, software utilitario y disposición de RAEE, y aplicarla en una primera inspección externa. Metodología pedagógica: aprendizaje colaborativo con estudio por bloques temáticos + inspección guiada.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-contexto\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128269;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Contextualización\u003c/h3\u003e\n              \u003cp\u003e2 actividades · Duración: 18 horas (10 directas + 8 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003c!-- ───────── Actividad 3.2.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eEstudio de contenidos de mantenimiento integral (Bloques A, B y C)\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión diagnóstica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Estudiar en equipo de 3 los 12 temas de los Bloques A, B y C, y consolidar una tabla resumen exportada a PDF: \u003ccode\u003eBloqueABC_RAP02_[TuNombre]_v1.0.pdf\u003c/code\u003e. Duración: 8 horas independientes + 6 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (8 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eEstudie los temas de los Bloques A, B y C usando el material de apoyo y los manuales técnicos que le indique el instructor. Tome apuntes en su bitácora. Llegue a clase con los conceptos básicos de mantenimiento físico (incluida la pasta térmica), lógico y disposición de RAEE revisados.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll u-mt-12\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth class=\"u-w-30\"\u003eTema (Bloque A — Arquitectura de hardware, tipos de mantenimiento y mantenimiento físico CRU)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eArquitectura de hardware\u003c/td\u003e\u003ctd\u003eConectores y buses actuales (SATA, M.2/NVMe, PCIe, USB-C): uso y velocidad aproximada.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eTipos de mantenimiento\u003c/td\u003e\u003ctd\u003ePreventivo, correctivo y predictivo: concepto, diferencias y ejemplos aplicados a equipos de cómputo actuales.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eComponentes CRU\u003c/td\u003e\u003ctd\u003eQué es un componente CRU (Customer Replaceable Unit) y ejemplos accesibles al técnico.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eElectricidad estática\u003c/td\u003e\u003ctd\u003eQué es la ESD (Electrostatic Discharge) y qué elementos de protección se deben usar (pulsera antiestática, superficie de trabajo).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eAplicación de pasta térmica\u003c/td\u003e\u003ctd\u003eQué es la pasta térmica, para qué sirve y cómo se retira la usada y se aplica la nueva correctamente sobre el procesador, evitando exceso o defecto.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll u-mt-12\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth class=\"u-w-30\"\u003eTema (Bloque B — Mantenimiento lógico)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eSistemas operativos\u003c/td\u003e\u003ctd\u003eInstalación y tipos de licenciamiento (OEM, retail, volumen, código abierto).\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eActualización y herramientas del sistema\u003c/td\u003e\u003ctd\u003eActualización del sistema operativo (Windows Update o equivalente) y utilidades incorporadas: liberador de espacio, administrador de tareas, información del sistema.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eSoftware utilitario de diagnóstico\u003c/td\u003e\u003ctd\u003eHerramientas de terceros para diagnóstico de hardware (por ejemplo, CPU-Z o HWMonitor) y para qué se usa cada una.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eAntivirus\u003c/td\u003e\u003ctd\u003eFunción del antivirus, tipos y buena práctica de mantener actualizada su base de datos de definiciones.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n              \u003cdiv class=\"table-scroll u-mt-12\"\u003e\n                \u003ctable class=\"data-table\"\u003e\n                  \u003cthead\u003e\n                    \u003ctr\u003e\n                      \u003cth class=\"u-w-30\"\u003eTema (Bloque C — Disposición de RAEE)\u003c/th\u003e\n                      \u003cth\u003e\u0026iquest;Qu\u0026eacute; debes aprender?\u003c/th\u003e\n                    \u003c/tr\u003e\n                  \u003c/thead\u003e\n                  \u003ctbody\u003e\n                    \u003ctr\u003e\u003ctd\u003eRAEE\u003c/td\u003e\u003ctd\u003eQué son los Residuos de Aparatos Eléctricos y Electrónicos y por qué requieren disposición especial.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eNormativa vigente\u003c/td\u003e\u003ctd\u003eResolución 1297 de 2010 y demás normativa ambiental colombiana aplicable a la gestión de RAEE.\u003c/td\u003e\u003c/tr\u003e\n                    \u003ctr\u003e\u003ctd\u003eClasificación de residuos\u003c/td\u003e\u003ctd\u003eCómo separar baterías, tarjetas, cables y empaques generados durante un mantenimiento.\u003c/td\u003e\u003c/tr\u003e\n                  \u003c/tbody\u003e\n                \u003c/table\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eForme un equipo de 3 personas. Repartan los 12 temas (5 del Bloque A + 4 del Bloque B + 3 del Bloque C): 4 temas por integrante.\u003c/li\u003e\n                  \u003cli\u003eDurante la primera hora, cada integrante explica sus temas al equipo (5 minutos por tema) mientras los demás completan sus apuntes.\u003c/li\u003e\n                  \u003cli\u003eEn LibreOffice Calc o Google Sheets, construyan una tabla de 3 columnas: «Tema», «¿Para qué sirve?», «Ejemplo aplicado en El Nogal». Completen una fila por tema.\u003c/li\u003e\n                  \u003cli\u003eEl instructor realiza una plenaria de cierre donde cada equipo comparte su fila más importante.\u003c/li\u003e\n                  \u003cli\u003eExporten la tabla a PDF con el nombre \u003cstrong\u003eBloqueABC_RAP02_[TuNombre]_v1.0.pdf\u003c/strong\u003e y compártanla por el medio indicado por el instructor.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eTabla resumen de los Bloques A, B y C en PDF (BloqueABC_RAP02_[TuNombre]_v1.0.pdf) y apuntes previos en la bitácora. Esta actividad alimenta la Actividad 3.2.2. Al finalizar el estudio de contenidos, el instructor aplica de forma individual el cuestionario de conocimiento (instrumento IE-01).\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eRegistro guiado del aprendiz\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Reparto del equipo: temas y responsable de cada uno\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_321_reparto\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Temas que estudiaste tú (4 de los 12 distribuidos en tu equipo)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_321_temas\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Tema de tu fila en la tabla resumen\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m2_321_tema_fila\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. ¿Para qué sirve?\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_321_paraque\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Ejemplo aplicado en El Nogal\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_321_ejemplo\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"bloqueABC321DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarBloqueABC321\" class=\"btn-save-response\" onclick=\"actStd_save_bloqueABC321()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_bloqueABC321()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusBloqueABC321\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-bloqueABC321\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.2.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.2.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eInspección externa e identificación de componentes CRU\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión diagnóstica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Inspeccionar externamente un equipo real del taller e identificar sus componentes CRU accesibles. Duración: 4 horas directas.\u003c/p\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones — sigue este orden sin saltarte pasos\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eEn equipo de máximo 4 integrantes, reciban del instructor un equipo de cómputo del taller (de escritorio, portátil o Todo en Uno, sin abrirlo todavía).\u003c/li\u003e\n                  \u003cli\u003eAntes de empezar, organicen el puesto de trabajo (herramientas, pulsera antiestática y un recipiente para residuos). Luego realicen una inspección puramente externa: estado físico de la carcasa, puertos, cables, ventilación y ruidos al encender.\u003c/li\u003e\n                  \u003cli\u003eIdentifiquen y registren en la tabla al menos 4 componentes CRU accesibles del equipo (por ejemplo: RAM, almacenamiento, ventilador, batería).\u003c/li\u003e\n                  \u003cli\u003eRedacten un informe corto (máximo 1 página) con sus conclusiones: ¿el equipo parece requerir mantenimiento físico, lógico, o ambos? Justifiquen con base en lo observado.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eInforme corto de inspección (máximo 1 página) y tabla de componentes CRU identificados, diligenciada. Formato: PDF o DOCX.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eInforme de inspección (registro del aprendiz)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Hallazgos de la inspección externa (carcasa, puertos, cables, ventilación, ruidos al encender)\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"m2_322_hallazgos\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Tabla de componentes CRU (mínimo 4): componente — ubicación en el equipo — estado observado\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"m2_322_cru\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Conclusión (máximo 1 página): ¿el equipo requiere mantenimiento físico, lógico o ambos? Justifica.\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"m2_322_conclusion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"inspeccionCru322DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarInspeccionCru322\" class=\"btn-save-response\" onclick=\"actStd_save_inspeccionCru322()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_inspeccionCru322()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusInspeccionCru322\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-inspeccionCru322\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.3 · ACTIVIDADES DE APROPIACIÓN DEL CONOCIMIENTO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"apropiacion\" class=\"section-title\"\u003e3.3 · Actividades de Apropiación del Conocimiento\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de apropiación:\u003c/strong\u003e pones en práctica lo aprendido sobre equipos reales.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003eEjecutar el mantenimiento preventivo físico CRU, incluida la aplicación de pasta térmica, y el mantenimiento lógico completo (sistema operativo y software utilitario) sobre equipos reales, aplicando el protocolo técnico revisado en la contextualización. Metodología pedagógica: estudio de caso + práctica guiada, con trabajo independiente previo de preparación.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-apropiacion\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128218;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Apropiación\u003c/h3\u003e\n              \u003cp\u003e2 actividades · Duración: 48 horas (38 directas + 10 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003carticle class=\"story-card u-mt-16\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso — Papelería y Miscelánea El Nogal: autorización para intervenir\u003c/h3\u003e\n                \u003cp\u003eDespués de la inspección externa de la Actividad 3.2.2, el propietario autoriza al equipo técnico a intervenir el computador de facturación: quiere que quede físicamente limpio, con el sistema operativo actualizado y con software de respaldo instalado, para no volver a perder información.\u003c/p\u003e\n              \u003c/article\u003e\n          \u003c!-- ───────── Actividad 3.3.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eMantenimiento preventivo físico CRU y aplicación de pasta térmica\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión práctica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Ejecutar el mantenimiento físico CRU sobre el equipo asignado y registrarlo en una ficha técnica. Duración: 6 horas independientes + 24 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (6 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eRepase el protocolo de limpieza interna y externa, las precauciones de manejo antiestático (ESD) y el procedimiento correcto de retiro y aplicación de pasta térmica, usando los manuales técnicos de fabricante recomendados por el instructor (equipos de escritorio, portátiles y Todo en Uno). Prepare una lista de los elementos de protección y herramientas que necesitará.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003ePrepare su sitio de trabajo y utilice los elementos de protección adecuados (pulsera antiestática, superficie de trabajo limpia).\u003c/li\u003e\n                  \u003cli\u003eVerifique que el equipo de facturación de El Nogal (o el equipo asignado por el instructor) esté apagado y desconectado de la red eléctrica antes de iniciar, y espere unos minutos antes de abrirlo.\u003c/li\u003e\n                  \u003cli\u003eRealice el diagnóstico interno del equipo, identificando los componentes CRU accesibles.\u003c/li\u003e\n                  \u003cli\u003eEjecute la limpieza interna (aire comprimido/brocha antiestática) y externa del equipo, según el manual del fabricante correspondiente.\u003c/li\u003e\n                  \u003cli\u003eRetire la pasta térmica usada del procesador (si el manual del fabricante lo permite) con un paño sin pelusa y alcohol isopropílico, y aplique pasta térmica nueva siguiendo el procedimiento indicado: una cantidad pequeña, centrada, sin exceso ni defecto.\u003c/li\u003e\n                  \u003cli\u003eVerifique y, si es necesario, reemplace o reubique componentes CRU accesibles, registrando cada paso realizado.\u003c/li\u003e\n                  \u003cli\u003eClasifique los materiales de desecho generados durante la intervención (por ejemplo, pasta térmica usada, paños, polvo) conforme al protocolo de manejo de RAEE y de residuos del instructor.\u003c/li\u003e\n                  \u003cli\u003eRegistre el procedimiento completo en una ficha técnica de mantenimiento (el formato lo suministra el instructor), con fecha, componentes intervenidos y observaciones, y tome fotos del antes y el después sin mostrar datos personales.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eFicha técnica de mantenimiento físico diligenciada, con registro fotográfico del antes/después. Formato: PDF o DOCX.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eRegistro guiado del aprendiz\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Preparación del sitio de trabajo y elementos de protección utilizados\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_331_preparacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Diagnóstico interno: componentes CRU accesibles identificados\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_331_diagnostico\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Limpieza interna y externa realizada (herramientas y pasos según el manual del fabricante)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_331_limpieza\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Retiro y aplicación de pasta térmica: procedimiento seguido y observaciones\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_331_pasta\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Componentes CRU verificados, reemplazados o reubicados (paso a paso)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_331_cru\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e6. Clasificación de los materiales de desecho generados (protocolo RAEE)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_331_residuos\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e7. Ficha técnica: fecha, componentes intervenidos y observaciones\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_331_ficha\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"fisicoCru331DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarFisicoCru331\" class=\"btn-save-response\" onclick=\"actStd_save_fisicoCru331()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_fisicoCru331()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusFisicoCru331\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-fisicoCru331\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.3.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.3.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eMantenimiento lógico: sistema operativo y software utilitario\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión práctica\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Ejecutar el mantenimiento lógico del equipo y registrarlo en un checklist con evidencias. Duración: 4 horas independientes + 14 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (4 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eInvestigue el procedimiento de actualización del sistema operativo instalado, los tipos de licenciamiento de software y el uso básico de una herramienta de diagnóstico de hardware (por ejemplo, CPU-Z o HWMonitor). Consulte el material de apoyo del instructor.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eVerifique el estado de actualizaciones del sistema operativo del equipo de facturación y aplique las actualizaciones pendientes, documentando la versión antes y después.\u003c/li\u003e\n                  \u003cli\u003eVerifique el estado y tipo de licenciamiento del sistema operativo instalado (OEM, retail, volumen o código abierto); en Windows se consulta en Configuración \u0026gt; Sistema \u0026gt; Activación. No use activadores ni programas de páginas no oficiales.\u003c/li\u003e\n                  \u003cli\u003eInstale o verifique una herramienta de software utilitario de diagnóstico de hardware (por ejemplo, CPU-Z o HWMonitor) y genere un reporte del estado del equipo.\u003c/li\u003e\n                  \u003cli\u003eInstale o verifique el antivirus del equipo y confirme que su base de datos de definiciones esté actualizada.\u003c/li\u003e\n                  \u003cli\u003eUtilice al menos una herramienta incorporada del sistema operativo (liberador de espacio, administrador de tareas o información del sistema) para verificar el estado general del equipo.\u003c/li\u003e\n                  \u003cli\u003eRegistre en un checklist (lista de tareas con una casilla por cada una) cada tarea realizada, con una captura de pantalla de cada paso (tecla Windows + Shift + S) guardada con nombre descriptivo, por ejemplo 01_Actualizaciones_[TuNombre].png.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eChecklist de mantenimiento lógico diligenciado, con capturas de pantalla de cada tarea. Formato: PDF o DOCX.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eChecklist de mantenimiento lógico (registro del aprendiz)\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Actualizaciones del sistema operativo: versión antes y después\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_332_actualizaciones\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Estado y tipo de licenciamiento del sistema operativo (OEM, retail, volumen o código abierto)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_332_licencia\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Herramienta de software utilitario de diagnóstico usada y resultado del reporte\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_332_utilitario\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Antivirus: estado y actualización de la base de datos de definiciones\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_332_antivirus\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Herramienta incorporada del sistema operativo utilizada y hallazgos\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_332_herramienta_so\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e6. Checklist: tareas realizadas y nombre de la captura que evidencia cada una\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"m2_332_checklist\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"logico332DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarLogico332\" class=\"btn-save-response\" onclick=\"actStd_save_logico332()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_logico332()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusLogico332\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-logico332\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ 3.4 · ACTIVIDADES DE TRANSFERENCIA DEL CONOCIMIENTO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"transferencia\" class=\"section-title\"\u003e3.4 · Actividades de Transferencia del Conocimiento\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eFase de transferencia:\u003c/strong\u003e aplicas todo lo aprendido en un laboratorio integrador y lo sustentas.\u003c/p\u003e\n      \u003cdiv class=\"info-box blue u-mb-16\"\u003e\n        \u003cp\u003eAplicar de forma integral y segura el mantenimiento físico (incluida la pasta térmica), el mantenimiento lógico y la disposición de RAEE sobre el equipo del caso, culminando en un informe técnico que se sustenta ante el instructor. Metodología pedagógica: estudio de caso + laboratorio integrador, con cierre mediante sustentación oral.\u003c/p\u003e\n      \u003c/div\u003e\n      \u003cdiv class=\"card open cat-transferencia\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon\"\u003e\u0026#128640;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eActividades de Transferencia\u003c/h3\u003e\n              \u003cp\u003e2 actividades · Duración: 20 horas (16 directas + 4 independientes)\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003carticle class=\"story-card u-mt-16\"\u003e\n                \u003ch3\u003e\u0026#128187; Caso — Papelería y Miscelánea El Nogal: cierre del proceso\u003c/h3\u003e\n                \u003cp\u003eEl propietario entrega también la batería de portátil dañada que tenía guardada y pide que el mantenimiento del equipo de facturación quede completamente documentado, incluyendo qué se hizo con los residuos generados, para poder mostrarlo si algún día lo necesita.\u003c/p\u003e\n              \u003c/article\u003e\n          \u003c!-- ───────── Actividad 3.4.1 ───────── --\u003e\n          \u003cdiv class=\"activity open mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.1\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eLaboratorio integrador: mantenimiento integral y disposición de RAEE\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión integradora\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Ejecutar el mantenimiento integral del equipo del caso y clasificar sus residuos. Duración: 2 horas independientes + 12 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (2 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eRepase sus registros de las Actividades 3.3.1 y 3.3.2, y consulte con el instructor o el material de apoyo el protocolo institucional de clasificación y disposición de RAEE (incluida la batería dañada).\u003c/p\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eEn equipo de máximo 3 integrantes, retomen el equipo de facturación de El Nogal (o el asignado por el instructor) y documenten su estado inicial.\u003c/li\u003e\n                  \u003cli\u003eEjecuten el mantenimiento preventivo físico CRU completo, incluida la aplicación de pasta térmica, aplicando lo trabajado en la Actividad 3.3.1.\u003c/li\u003e\n                  \u003cli\u003eEjecuten el mantenimiento lógico del equipo (actualización de sistema operativo, verificación de licenciamiento, software utilitario), aplicando lo trabajado en la Actividad 3.3.2.\u003c/li\u003e\n                  \u003cli\u003eClasifiquen los residuos generados durante el proceso, incluida la batería dañada entregada por el propietario (sin manipularla: el instructor indica cómo hacerlo), según la normativa ambiental vigente (Resolución 1297 de 2010) y el protocolo institucional.\u003c/li\u003e\n                  \u003cli\u003eRegistren el punto o gestor autorizado de recolección de RAEE al que se dispondrían los residuos clasificados.\u003c/li\u003e\n                  \u003cli\u003eVerifiquen el funcionamiento final del equipo (encendido, aplicaciones básicas, acceso a internet).\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eRegistro de laboratorio integrador (estado inicial, procedimiento físico y lógico, resultados) y evidencia de la clasificación/disposición de RAEE. Formato: PDF o DOCX.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eRegistro del laboratorio integrador\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Estado inicial del equipo\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_341_estado_inicial\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Mantenimiento físico CRU realizado (incluida la pasta térmica)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_341_fisico\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Mantenimiento lógico realizado (sistema operativo, licenciamiento, software utilitario)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_341_logico\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Clasificación de los residuos generados, incluida la batería dañada (Resolución 1297 de 2010)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_341_raee\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Punto o gestor autorizado de recolección de RAEE al que se dispondrían los residuos\u003c/span\u003e\n                  \u003ctextarea rows=\"2\" data-store=\"m2_341_gestor\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e6. Verificación final del funcionamiento (encendido, aplicaciones básicas, internet)\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_341_verificacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"integrador341DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarIntegrador341\" class=\"btn-save-response\" onclick=\"actStd_save_integrador341()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_integrador341()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusIntegrador341\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-integrador341\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n          \u003c!-- ───────── Actividad 3.4.2 ───────── --\u003e\n          \u003cdiv class=\"activity mission-card\"\u003e\n            \u003cdiv class=\"activity-header\" onclick=\"toggleActivity(this.parentElement)\"\u003e\n              \u003cspan class=\"activity-num\"\u003e3.4.2\u003c/span\u003e\n              \u003cspan class=\"activity-title\"\u003eInforme técnico final y sustentación\u003c/span\u003e\n              \u003cspan class=\"mission-chip\"\u003eMisión integradora\u003c/span\u003e\n              \u003cspan class=\"activity-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n            \u003c/div\u003e\n            \u003cdiv class=\"activity-body\"\u003e\n              \u003cp class=\"intro-text\"\u003e\u003cstrong\u003eProp\u0026oacute;sito:\u003c/strong\u003e Elaborar el informe técnico final del mantenimiento integral y sustentarlo ante el instructor. Duración: 2 horas independientes + 4 horas directas.\u003c/p\u003e\n              \u003cdiv class=\"info-box u-mt-14\"\u003e\n                \u003cdiv class=\"label\"\u003e\u0026#9200; Trabajo independiente (2 horas, ANTES de la sesión directa)\u003c/div\u003e\n                \u003cp\u003eRedacten el borrador del informe técnico final con base en los registros de la Actividad 3.4.1, y preparen la sustentación oral.\u003c/p\u003e\n              \u003c/div\u003e\n              \u003carticle class=\"support-card u-mt-16\"\u003e\n                \u003ch3\u003eInstrucciones para la sesión directa\u003c/h3\u003e\n                \u003col class=\"u-steps\"\u003e\n                  \u003cli\u003eEn el mismo equipo de trabajo, elaboren el informe técnico final de mantenimiento integral del equipo de El Nogal, incluyendo: diagnóstico inicial, procedimiento físico y lógico realizado, resultados, y disposición de RAEE.\u003c/li\u003e\n                  \u003cli\u003eAnexen al informe la ficha técnica diligenciada en la Actividad 3.3.1 y el checklist de la Actividad 3.3.2.\u003c/li\u003e\n                  \u003cli\u003ePreparen una sustentación oral de máximo 10 minutos por equipo, explicando el informe con lenguaje sencillo, como si se lo presentaran directamente al propietario del negocio. Participan todos los integrantes.\u003c/li\u003e\n                  \u003cli\u003eSustenten ante el instructor y sus compañeros. El instructor evalúa dominio técnico, claridad de la explicación y pertinencia de las recomendaciones frente al caso.\u003c/li\u003e\n                  \u003cli\u003eEntreguen el informe técnico final en formato digital, incluyendo la ficha técnica y el checklist como anexos.\u003c/li\u003e\n                \u003c/ol\u003e\n              \u003c/article\u003e\n              \u003cdiv class=\"gnote gnote--entrega u-mt-14\"\u003e\u003cdiv class=\"gnote__label\"\u003e\u0026#128230; \u0026iquest;Qu\u0026eacute; debes entregar?\u003c/div\u003e\n                \u003cp\u003eInforme técnico final completo (DOCX o PDF) con anexos de ficha técnica y checklist, y sustentación oral ante el instructor.\u003c/p\u003e\u003c/div\u003e\n              \u003carticle class=\"notes-card u-mt-16\"\u003e\n                \u003ch3\u003eBorrador del informe técnico final\u003c/h3\u003e\n                \u003cp class=\"intro-text u-help-note\"\u003e\u0026#9998; Campos de apoyo del portal para organizar tus respuestas: no reemplazan las instrucciones ni las evidencias de la gu\u0026iacute;a.\u003c/p\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e1. Diagnóstico inicial\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_342_diagnostico\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e2. Procedimiento físico y lógico realizado\u003c/span\u003e\n                  \u003ctextarea rows=\"5\" data-store=\"m2_342_procedimiento\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e3. Resultados obtenidos\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_342_resultados\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e4. Disposición de RAEE\u003c/span\u003e\n                  \u003ctextarea rows=\"3\" data-store=\"m2_342_raee\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003clabel\u003e\n                  \u003cspan\u003e5. Puntos clave y recomendaciones para la sustentación ante el propietario (máximo 10 minutos)\u003c/span\u003e\n                  \u003ctextarea rows=\"4\" data-store=\"m2_342_sustentacion\" data-track placeholder=\"Escribe aqu\u0026iacute; tu respuesta.\"\u003e\u003c/textarea\u003e\n                \u003c/label\u003e\n                \u003cdiv class=\"u-mt-16\" id=\"informeFinal342DeadlineControls\"\u003e\u003c/div\u003e\n                \u003cdiv class=\"act-btn-group\"\u003e\n                  \u003cbutton type=\"button\" id=\"btnGuardarInformeFinal342\" class=\"btn-save-response\" onclick=\"actStd_save_informeFinal342()\"\u003e\n                    \u0026#128190; Guardar respuestas\n                  \u003c/button\u003e\n                  \u003cbutton type=\"button\" class=\"btn-export-word\" onclick=\"actStd_export_informeFinal342()\"\u003e\n                    \u0026#128196; Exportar a Word\n                  \u003c/button\u003e\n                \u003c/div\u003e\n                \u003cdiv id=\"statusInformeFinal342\" class=\"activity-saved-notice u-saved\"\u003e\n                  \u0026#9989; Respuestas guardadas correctamente.\n                \u003c/div\u003e\n              \u003c/article\u003e\n\n              \u003cdiv class=\"u-mt-16\" id=\"driveDeliveryPanel-informeFinal342\"\u003e\u003c/div\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ MATERIALES DE APOYO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"materiales\" class=\"section-title\"\u003eMateriales de Apoyo\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eConsulta aquí\u003c/strong\u003e los documentos de referencia y las herramientas que necesitas para las actividades de esta guía.\u003c/p\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-teal\"\u003e\u0026#128193;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eDocumentos y herramientas\u003c/h3\u003e\n              \u003cp\u003eMaterial de apoyo suministrado por el instructor\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\u003cth\u003eMaterial\u003c/th\u003e\u003cth\u003eActividad\u003c/th\u003e\u003cth\u003eEnlace\u003c/th\u003e\u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\u003ctd\u003eResolución 1297 de 2010 — Gestión de RAEE (Colombia)\u003c/td\u003e\u003ctd\u003e3.2.1 · 3.3.1 · 3.4.1\u003c/td\u003e\u003ctd\u003e\u003ca href=\"assets/materiales/guia6mant/resolucion-1297-de-2010.pdf\" target=\"_blank\" rel=\"noopener\"\u003eAbrir PDF\u003c/a\u003e\u003c/td\u003e\u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128295; Herramientas de diagnóstico de hardware (Actividad 3.3.2)\u003c/div\u003e\n            \u003cp\u003eCPU-Z y HWMonitor se descargan del sitio oficial del fabricante: \u003ca href=\"https://www.cpuid.com/softwares/cpu-z.html\" target=\"_blank\" rel=\"noopener\"\u003eCPU-Z\u003c/a\u003e · \u003ca href=\"https://www.cpuid.com/softwares/hwmonitor.html\" target=\"_blank\" rel=\"noopener\"\u003eHWMonitor\u003c/a\u003e. No use instaladores de páginas no oficiales.\u003c/p\u003e\n          \u003c/div\u003e\n          \u003cdiv class=\"info-box u-mt-14\"\u003e\n            \u003cdiv class=\"label\"\u003e\u0026#128194; Material de apoyo que entrega el instructor\u003c/div\u003e\n            \u003cp\u003eEstos documentos del material de apoyo de la gu\u0026iacute;a todav\u0026iacute;a no est\u0026aacute;n publicados en el portal. Sol\u0026iacute;citalos a tu instructor:\u003c/p\u003e\n            \u003cul class=\"u-steps-top\"\u003e\u003cli\u003eManual de Mantenimiento de Computadores (Hardware y Software)\u003c/li\u003e\u003cli\u003eManual de Solución de Fallas — HP Compaq dc5700 (Escritorio)\u003c/li\u003e\u003cli\u003eManual Equipo Todo en Uno — HP Pavilion\u003c/li\u003e\u003cli\u003eManual Portátil HP — Guía del Usuario\u003c/li\u003e\u003cli\u003eManual Portátil Acer Aspire E15\u003c/li\u003e\u003c/ul\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ EVIDENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"evidencias\" class=\"section-title\"\u003ePlanteamiento de Evidencias para la Evaluaci\u0026oacute;n\u003c/div\u003e\n      \u003cp class=\"section-intro\"\u003e📍 \u003cstrong\u003eResumen de lo que debes entregar:\u003c/strong\u003e usa esta sección como lista de chequeo final.\u003c/p\u003e\n      \u003cdiv class=\"gnote gnote--entrega\"\u003e\u003cdiv class=\"gnote__label\"\u003e📦 Antes de entregar, revisa\u003c/div\u003e\n        \u003cul\u003e\n          \u003cli\u003eRespondiste todas las actividades que se piden como evidencia.\u003c/li\u003e\n          \u003cli\u003eTus archivos tienen tu nombre y número de ficha.\u003c/li\u003e\n          \u003cli\u003eSubiste cada evidencia con el botón \u003cem\u003eEntregar a Drive\u003c/em\u003e y la ves marcada como \u003cstrong\u003eEntregada\u003c/strong\u003e en tu control de avance.\u003c/li\u003e\n        \u003c/ul\u003e\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-blue\"\u003e\u0026#128202;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eTabla de Evidencias del Proceso Formativo\u003c/h3\u003e\n              \u003cp\u003e3 evidencias: conocimiento, desempe\u0026ntilde;o y producto\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdiv class=\"table-scroll\"\u003e\n            \u003ctable class=\"data-table\"\u003e\n              \u003cthead\u003e\n                \u003ctr\u003e\u003cth\u003eActividad de Aprendizaje\u003c/th\u003e\u003cth\u003eEvidencias\u003c/th\u003e\u003cth\u003eCriterios\u003c/th\u003e\u003cth\u003eInstrumento\u003c/th\u003e\u003c/tr\u003e\n              \u003c/thead\u003e\n              \u003ctbody\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.2.1 + 3.2.2 — Estudio de contenidos e inspección externa\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003eCONOCIMIENTO:\u003c/strong\u003e cuestionario sobre procedimientos de mantenimiento de componentes CRU, aplicación de pasta térmica y normativa RAEE.\u003c/td\u003e\n                  \u003ctd\u003eEjecuta el mantenimiento preventivo integral CRU según el diagnóstico. Utiliza los sistemas operativos y herramientas del sistema según condiciones técnicas.\u003c/td\u003e\n                  \u003ctd\u003eIE-01 — Cuestionario de conocimiento\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.3.1 + 3.3.2 — Mantenimiento físico CRU y mantenimiento lógico del sistema\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003eDESEMPEÑO:\u003c/strong\u003e ejecución práctica completa del mantenimiento integral de un equipo de cómputo real en el taller: desensamble, limpieza, aplicación de pasta térmica, ensamble y verificación básica.\u003c/td\u003e\n                  \u003ctd\u003eEjecuta el mantenimiento preventivo integral CRU según el diagnóstico. Utiliza los sistemas operativos y herramientas del sistema según condiciones técnicas.\u003c/td\u003e\n                  \u003ctd\u003eIE-02 — Lista de chequeo de desempeño\u003c/td\u003e\n                \u003c/tr\u003e\n                \u003ctr\u003e\n                  \u003ctd\u003e3.4.1 + 3.4.2 — Laboratorio integrador y disposición de RAEE\u003c/td\u003e\n                  \u003ctd\u003e\u003cstrong\u003ePRODUCTO:\u003c/strong\u003e informe técnico final de mantenimiento integral, con registro fotográfico del proceso, evidencia de disposición correcta de residuos RAEE y sustentación oral.\u003c/td\u003e\n                  \u003ctd\u003eDispone los residuos RAEE en la fuente según normatividad.\u003c/td\u003e\n                  \u003ctd\u003eIE-03 — Lista de chequeo de producto\u003c/td\u003e\n                \u003c/tr\u003e\n              \u003c/tbody\u003e\n            \u003c/table\u003e\n          \u003c/div\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ GLOSARIO ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"glosario\" class=\"section-title\"\u003eGlosario de T\u0026eacute;rminos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-orange\"\u003e\u0026#128214;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eConceptos clave\u003c/h3\u003e\n              \u003cp\u003e15 t\u0026eacute;rminos t\u0026eacute;cnicos\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003cdl class=\"glossary-list\"\u003e\n            \u003cdt\u003eMantenimiento preventivo\u003c/dt\u003e\u003cdd\u003eConjunto de acciones programadas y realizadas de forma periódica sobre un equipo de cómputo con el fin de evitar fallas antes de que ocurran, prolongando su vida útil.\u003c/dd\u003e\n            \u003cdt\u003eMantenimiento correctivo\u003c/dt\u003e\u003cdd\u003eIntervención que se realiza sobre un equipo de cómputo después de que se ha presentado una falla, con el propósito de restablecer su funcionamiento normal.\u003c/dd\u003e\n            \u003cdt\u003eMantenimiento predictivo\u003c/dt\u003e\u003cdd\u003eConjunto de técnicas que permiten anticipar una falla mediante el monitoreo de variables del equipo.\u003c/dd\u003e\n            \u003cdt\u003eCRU (Customer Replaceable Unit)\u003c/dt\u003e\u003cdd\u003eComponente o unidad de un equipo de cómputo que puede ser reemplazada directamente por el usuario o técnico, sin necesidad de intervención especializada del fabricante.\u003c/dd\u003e\n            \u003cdt\u003eESD (Electrostatic Discharge)\u003c/dt\u003e\u003cdd\u003eDescarga electrostática que puede dañar componentes electrónicos sensibles si no se toman las precauciones adecuadas (uso de pulsera antiestática, superficies de trabajo aterrizadas).\u003c/dd\u003e\n            \u003cdt\u003eNVMe / M.2\u003c/dt\u003e\u003cdd\u003eInterfaz y factor de forma modernos para unidades de almacenamiento de estado sólido, de mayor velocidad que las interfaces SATA tradicionales.\u003c/dd\u003e\n            \u003cdt\u003eSoftware utilitario\u003c/dt\u003e\u003cdd\u003eConjunto de programas de apoyo, como herramientas de diagnóstico de hardware y antivirus, que facilitan el mantenimiento lógico de un equipo de cómputo.\u003c/dd\u003e\n            \u003cdt\u003ePasta térmica\u003c/dt\u003e\u003cdd\u003eSustancia conductora del calor que se aplica entre el procesador (o la GPU) y su disipador para mejorar la transferencia térmica; debe renovarse periódicamente como parte del mantenimiento preventivo físico.\u003c/dd\u003e\n            \u003cdt\u003eRAEE\u003c/dt\u003e\u003cdd\u003eResiduos de Aparatos Eléctricos y Electrónicos: desechos generados por equipos electrónicos en desuso, que requieren disposición especial según normatividad ambiental vigente.\u003c/dd\u003e\n            \u003cdt\u003eDiagnóstico\u003c/dt\u003e\u003cdd\u003eProceso de identificar, mediante observación y pruebas, el estado de un equipo y las posibles causas de una falla.\u003c/dd\u003e\n            \u003cdt\u003eLicenciamiento\u003c/dt\u003e\u003cdd\u003eTipo de permiso de uso de un programa: OEM (viene incluida con el computador), retail (se compra por separado), volumen (para muchos equipos de una organización) y código abierto (de uso libre, como Linux).\u003c/dd\u003e\n            \u003cdt\u003eAntivirus\u003c/dt\u003e\u003cdd\u003ePrograma que detecta y elimina software malicioso; necesita mantener actualizada su base de definiciones.\u003c/dd\u003e\n            \u003cdt\u003eChecklist\u003c/dt\u003e\u003cdd\u003eLista de tareas con una casilla por cada una, que permite comprobar que no se omitió ningún paso.\u003c/dd\u003e\n            \u003cdt\u003eBitácora\u003c/dt\u003e\u003cdd\u003eCuaderno o documento donde el aprendiz anota apuntes, datos y observaciones de su trabajo.\u003c/dd\u003e\n            \u003cdt\u003eCaptura de pantalla\u003c/dt\u003e\u003cdd\u003eImagen de lo que se ve en la pantalla; en Windows se toma con las teclas Windows + Shift + S.\u003c/dd\u003e\n          \u003c/dl\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n      \u003c!-- ╔═══════════════════════ REFERENCIAS ═══════════════════════╗ --\u003e\n      \u003cdiv id=\"referencias\" class=\"section-title\"\u003eReferentes Bibliogr\u0026aacute;ficos\u003c/div\u003e\n      \u003cdiv class=\"card\"\u003e\n        \u003cdiv class=\"card-header\" onclick=\"toggleCard(this.parentElement)\"\u003e\n          \u003cdiv class=\"card-header-left\"\u003e\n            \u003cdiv class=\"card-icon u-bg-purple\"\u003e\u0026#128279;\u003c/div\u003e\n            \u003cdiv\u003e\n              \u003ch3\u003eFuentes oficiales y normativas\u003c/h3\u003e\n              \u003cp\u003e6 referencias para consulta\u003c/p\u003e\n            \u003c/div\u003e\n          \u003c/div\u003e\n          \u003cspan class=\"card-toggle\"\u003e\u0026#9662;\u003c/span\u003e\n        \u003c/div\u003e\n        \u003cdiv class=\"card-body\"\u003e\n          \u003col class=\"references-list u-refs\"\u003e\n            \u003cli\u003eCisco Networking Academy. \u003cem\u003eIT Essentials: PC Hardware and Software (v8.0)\u003c/em\u003e. \u003ca href=\"https://www.netacad.com\" target=\"_blank\" rel=\"noopener\"\u003enetacad.com\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eServicio Nacional de Aprendizaje — SENA. \u003cem\u003eDiseño Curricular Técnico en Sistemas Teleinformáticos\u003c/em\u003e, versión 233108. SENA, Regional Boyacá.\u003c/li\u003e\n            \u003cli\u003eServicio Nacional de Aprendizaje — SENA. \u003cem\u003eBiblioteca Virtual SENA\u003c/em\u003e. \u003ca href=\"https://biblioteca.sena.edu.co\" target=\"_blank\" rel=\"noopener\"\u003ebiblioteca.sena.edu.co\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003eMinisterio de Ambiente y Desarrollo Sostenible. \u003cem\u003eResolución 1297 de 2010\u003c/em\u003e sobre gestión de Residuos de Aparatos Eléctricos y Electrónicos (RAEE). Colombia. \u003ca href=\"assets/materiales/guia6mant/resolucion-1297-de-2010.pdf\" target=\"_blank\" rel=\"noopener\"\u003eResolución 1297/2010 (PDF)\u003c/a\u003e\u003c/li\u003e\n            \u003cli\u003e\u003cem\u003eManual de Mantenimiento de Computadores (Hardware y Software)\u003c/em\u003e. Material de apoyo institucional para procedimientos de mantenimiento físico y lógico de equipos de cómputo.\u003c/li\u003e\n            \u003cli\u003eManuales técnicos de fabricantes de equipos de cómputo (HP, Acer) para procedimientos de mantenimiento CRU y diagnóstico de fallas.\u003c/li\u003e\n          \u003c/ol\u003e\n        \u003c/div\u003e\n      \u003c/div\u003e\n\n    \u003c/div\u003e\n  \u003c/div\u003e\n\u003c/div\u003e\n";
